function PreviewHelpPage(){const {data,state,openSheet}=React.useContext(AppContext);return <section className="stack help-page"><h1>About this preview</h1><p>This is an isolated rehearsal with sample profiles, posts, orders and activity.</p><p>Changes stay on this device. The preview never sends family messages, invitations or payments, and doesn't grant access to private accounts.</p>{state.mode==='preview'&&<Button secondary onClick={()=>openSheet({type:'preview-reset'})}>Reset local preview</Button>}{data.config?.configured&&<Button onClick={data.leavePreview}>Sign in to the family</Button>}</section>}
function FilterChoices({kind}){const {state,dispatch}=React.useContext(AppContext),field=kind==='feed'?'feedFilter':'peopleFilter',type=kind==='feed'?'SET_FEED_FILTER':'SET_PEOPLE_FILTER';return <div className="filter-choices" role="group" aria-label="Show updates from">{[['all','All'],['family','Family'],['loved','Loved Ones'],['leaders','Leaders']].map(([value,label])=><Control key={value} className="filter-option" aria-pressed={state[field]===value} onClick={()=>dispatch({type,value})}><span>{label}</span>{state[field]===value&&<Glyph name="check"/>}</Control>)}</div>}
function linkInfo(url){try{const u=new URL(url),h=u.hostname.toLowerCase();if(u.protocol!=='https:'||u.username||u.password||u.port)return null;if(h==='open.spotify.com'&&/^\/(track|playlist)\/[A-Za-z0-9]{22}\/?$/.test(u.pathname)){const parts=u.pathname.split('/');return {service:'Spotify',url:u.origin+'/'+parts[1]+'/'+parts[2],embed:'https://open.spotify.com/embed/'+parts[1]+'/'+parts[2],type:parts[1]}}if(h==='music.apple.com'&&u.pathname.includes('/album/'))return {service:'Apple Music',url:u.href,embed:'https://embed.music.apple.com'+u.pathname,type:u.searchParams.has('i')?'song':'playlist'};}catch{}return null}
