function ProfileMenuContent({open,member,page,setPage}){const{state,data,go,openSheet,platform,setPlatform}=React.useContext(AppContext);return <div className="stack pop-content profile-menu" data-menu-page={page}>{page==='appearance'?<div key="appearance" className="menu-subpage"><div className="appearance-panel-heading"><Control className="appearance-back" aria-label="Back to profile menu" onClick={()=>setPage('main')}><svg className="glyph" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M20 12H4m6-6-6 6 6 6" strokeLinecap="round" strokeLinejoin="round"/></svg></Control><h3>Appearance</h3></div><AppearanceChoices/><fieldset className="appearance-material"><legend>Style</legend><div className="segmented" role="group" aria-label="Interface material"><Control aria-pressed={platform==='ios'} onClick={()=>setPlatform('ios')}>Glass</Control><Control aria-pressed={platform==='android'} onClick={()=>setPlatform('android')}>Flat</Control></div></fieldset><TextSizeControls/><Button secondary className="appearance-full-width" onClick={()=>go({type:'appearance'})}>Open full Appearance</Button></div>:<div key="main" className="stack menu-subpage"><div className="profile-summary"><Avatar member={member}/><span><strong>{member.name}</strong><small>Your family profile</small></span></div><Button icon="user" onClick={()=>go({type:'you'})}>Go to You</Button><ActionRow icon="settings" title="Appearance" detail="Style, color, and text size" onClick={()=>setPage('appearance')}/><ActionRow tourTarget="you-guide" icon="people" title="Quick guide" detail="Explore or replay the basics" onClick={()=>openSheet({type:'tutorial'})}/><ActionRow icon="home" title="Add to Homescreen" detail="Keep your family close" onClick={()=>openSheet({type:'install'})}/>{state.mode==='preview'?<PreviewAccountControls compact/>:<SignOutControl/>}</div>}</div>}
function TextSizeControls(){const{textStep,setTextStep}=React.useContext(AppContext);return <fieldset className="text-size-controls"><legend>Text size</legend><div className="text-size-stepper"><Control aria-label="Smaller text" disabled={textStep===0} onClick={()=>setTextStep(n=>Math.max(0,n-1))}><span className="small-aa">Aa</span></Control><output aria-live="polite">{textStep===1?'System':Math.round(textSizes[textStep]*100)+'%'}</output><Control aria-label="Larger text" disabled={textStep===textSizes.length-1} onClick={()=>setTextStep(n=>Math.min(textSizes.length-1,n+1))}><span className="large-aa">Aa</span></Control></div><Control className="text-button" onClick={()=>setTextStep(1)}>System default</Control></fieldset>}

function FirstViewAnnouncement(){const{state,dispatch,go}=React.useContext(AppContext),[busy,setBusy]=useState(false),[dismissed,setDismissed]=useState([]);const p=state.posts.find(p=>p.firstView&&p.asLeader&&p.authorId!==state.selfId&&!(state.announcementViews||[]).includes(p.id)&&!dismissed.includes(p.id));if(!p)return null;const acknowledge=async(open=false)=>{setBusy(true);try{if(await dispatch({type:'MARK_ANNOUNCEMENT_SEEN',id:p.id})){setDismissed(v=>[...v,p.id]);if(open)go({type:'post',id:p.id})}}finally{setBusy(false)}};return <Sheet title="A note from your family leaders" busy={busy} onClose={()=>acknowledge()}><div className="stack">{p.textFormat==='markdown'?<PageMarkdownBody source={p.text}/>:<p>{p.text}</p>}<div className="row"><Button disabled={busy} onClick={()=>acknowledge(true)}>View post</Button><Button secondary disabled={busy} onClick={()=>acknowledge()}>Got it</Button></div></div></Sheet>}

function BuildUpdateNotice(){const {data,state,messaging}=React.useContext(AppContext),pageContent=usePageContent(),[ready,setReady]=useState(null),[deferred,setDeferred]=useState(null);useEffect(()=>watchBuild(setReady),[]);const pending=data.pending||pageContent.pending,drafts=data.hasLocalDrafts||hasChatDrafts(state.selfId)||messaging.draftStorageOk===false||pageContent.hasUnsavedDrafts,safe=pageContent.storageSafe!==false&&data.draftStorageStatus?.ok!==false&&!data.draftStorageStatus?.omittedMedia&&messaging.draftStorageOk!==false;return ready&&deferred===ready?<aside className="build-update-reminder"><button type="button" onClick={()=>setDeferred(null)}>Update ready</button></aside>:ready?<aside className="build-update-notice" role="status"><span>{pending?'A newer version is ready. Waiting for your changes to finish.':drafts?safe?'A newer version is ready. Your text drafts will stay here after reloading.':'A newer version is ready. Keep this page open until you save your draft.':'A newer version is ready.'}</span><div className="build-update-actions"><button type="button" disabled={pending||drafts&&!safe} onClick={()=>{if(pageContent.prepareReload?.()===false)return;window.location.reload()}}>Reload updated app</button><button type="button" className="update-later" onClick={()=>setDeferred(ready)}>Later</button></div></aside>:null}

import './navigation-insets.css';

